SOURCES={
 'ies':('IES · 학습을 돕는 수업과 공부 방법','https://ies.ed.gov/ncee/wwc/practiceguide/1'),
 'meta':('EEF · 계획·점검·평가를 통한 자기조절학습','https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/metacognition'),
 'feedback':('EEF · 학습에 활용하는 피드백','https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/feedback'),
 'parents':('EEF · 가정과 함께 학습을 돕는 방법','https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/supporting-parents'),
 'digital':('EEF · 교육에서 디지털 도구를 활용하는 방법','https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/digital'),
 'styles':('EEF · 고정된 학습 유형 분류의 근거 검토','https://educationendowmentfoundation.org.uk/education-evidence/teaching-learning-toolkit/learning-styles'),
 'sleep':('CDC · 아동·청소년의 수면 시간','https://www.cdc.gov/healthy-schools/sleep/index.html'),
 'stress':('NIMH · 스트레스 신호와 도움을 구하는 방법','https://www.nimh.nih.gov/health/publications/so-stressed-out-fact-sheet'),
 'literacy':('EEF · 중등 읽기·쓰기와 교과 어휘 학습','https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/literacy-ks3-ks4'),
}
